#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
using namespace std;

const int INF = 0x3f3f3f3f;
const int MAXN = 20;
const int MAXV = 2 * MAXN * MAXN;

char grid1[MAXN][MAXN], grid2[MAXN][MAXN];
int dist_time[MAXN][MAXN];
int n, t;

int directions[] = {1, 0, -1, 0};
int directionsY[] = {0, 1, 0, -1};

void compute_bfs(int startX, int startY) {
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            dist_time[i][j] = INF;
    dist_time[startX][startY] = 0;
    queue<pair<int, int>> q;
    q.push({startX, startY});
    while (!q.empty()) {
        auto [x, y] = q.front(); q.pop();
        for (int dir = 0; dir < 4; ++dir) {
            int nx = x + directions[dir], ny = y + directionsY[dir];
            if (nx >= n || ny >= n || nx < 0 || ny < 0) continue;
            if ('0' <= grid1[nx][ny] && grid1[nx][ny] <= '9' && dist_time[nx][ny] == INF) {
                dist_time[nx][ny] = dist_time[x][y] + 1;
                q.push({nx, ny});
            }
        }
    }
}

vector<int> adj_list[MAXV];
int capacity[MAXV][MAXV];

void addEdge(int u, int v, int c) {
    adj_list[u].push_back(v);
    adj_list[v].push_back(u);
    capacity[u][v] = c;
    capacity[v][u] = 0;
}

int time_grid[MAXN][MAXN];
bool visited_nodes[MAXV];
int level[MAXV];

bool build_level_graph(int s, int t) {
    memset(level, -1, sizeof(level));
    level[s] = 0;
    queue<int> q;
    q.push(s);
    while (!q.empty() && level[t] == -1) {
        int v = q.front(); q.pop();
        for (auto &nxt : adj_list[v]) {
            if (!capacity[v][nxt] || level[nxt] != -1) continue;
            level[nxt] = level[v] + 1;
            q.push(nxt);
        }
    }
    return level[t] != -1;
}

void explore_bfs(int px, int py) {
    memset(time_grid, INF, sizeof(time_grid));
    time_grid[px][py] = 0;
    if ('1' <= grid2[px][py] && grid2[px][py] <= '9')
        addEdge(n * px + py, n * n + n * px + py, INF);
    queue<pair<int, int>> q;
    q.push({px, py});
    while (!q.empty()) {
        auto [x, y] = q.front(); q.pop();
        for (int dir = 0; dir < 4; ++dir) {
            int nx = x + directions[dir], ny = y + directionsY[dir];
            if (nx >= n || ny >= n || nx < 0 || ny < 0) continue;
            if (time_grid[nx][ny] != INF) continue;
            if (!('0' <= grid1[nx][ny] && grid1[nx][ny] <= '9')) continue;
            if (time_grid[x][y] + 1 <= min(dist_time[nx][ny] - 1, t)) {
                time_grid[nx][ny] = time_grid[x][y] + 1;
                q.push({nx, ny});
            }
            if (time_grid[x][y] + 1 <= min(dist_time[nx][ny], t) && '1' <= grid2[nx][ny] && grid2[nx][ny] <= '9')
                addEdge(n * px + py, n * n + n * nx + ny, INF);
        }
    }
}

int dinic_search(int v, int t, int flow) {
    if (v == t) return flow;
    visited_nodes[v] = true;
    for (auto &nxt : adj_list[v]) {
        if (!capacity[v][nxt] || visited_nodes[nxt] || level[nxt] != level[v] + 1) continue;
        int pushed = dinic_search(nxt, t, min(flow, capacity[v][nxt]));
        if (pushed) {
            capacity[v][nxt] -= pushed;
            capacity[nxt][v] += pushed;
            return pushed;
        }
    }
    return 0;
}

int compute_max_flow(int s, int t) {
    int total_flow = 0, flow;
    while (build_level_graph(s, t)) {
        memset(visited_nodes, 0, sizeof(visited_nodes));
        while ((flow = dinic_search(s, t, INF)) > 0) {
            total_flow += flow;
            memset(visited_nodes, 0, sizeof(visited_nodes));
        }
    }
    return total_flow;
}

int main() {
    cin >> n >> t;
    int start_x, start_y;
    int source = MAXV - 2, sink = MAXV - 1;
    for (int a = 0; a < n; ++a) {
        for (int b = 0; b < n; ++b) {
            cin >> grid1[a][b];
            if (grid1[a][b] == 'Z') {
                start_x = a; start_y = b;
            } else if ('1' <= grid1[a][b] && grid1[a][b] <= '9') {
                addEdge(source, a * n + b, grid1[a][b] - '0');
            }
        }
    }
    compute_bfs(start_x, start_y);
    for (int a = 0; a < n; ++a) {
        for (int b = 0; b < n; ++b) {
            cin >> grid2[a][b];
            if ('1' <= grid2[a][b] && grid2[a][b] <= '9') {
                addEdge(n * n + a * n + b, sink, grid2[a][b] - '0');
            }
        }
    }
    for (int a = 0; a < n; ++a) {
        for (int b = 0; b < n; ++b) {
            if ('1' <= grid1[a][b] && grid1[a][b] <= '9') {
                explore_bfs(a, b);
            }
        }
    }
    cout << compute_max_flow(source, sink) << "\n";
    return 0;
}
